/**
 * 0.8.0：把年度总结的单一数据源同步到前后端。
 *
 *   code/shared/annual-review.mjs ──► code/app/lib/annual-review.mjs
 *                                 ──► code/web/src/js/lib/annual-review.js
 *   code/shared/qr.mjs           ──► code/app/lib/qr.mjs
 *                                 ──► code/web/src/js/lib/qr.js
 *
 * 生成物带 AUTO-GENERATED 头注释；前端生成物把 `./qr.mjs` 改成 `./qr.js`
 * （vite 侧沿用 .js 后缀），其余逐字一致。`tests/annual-shared-080.test.js`
 * 与 `app/test/m80-annual.test.mjs` 断言之与源文件一致，漂移即失败。
 *
 * 用法：
 *   node scripts/sync-annual.mjs            # 写入
 *   node scripts/sync-annual.mjs --check    # 只检查，漂移时 exit 1
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const codeRoot = join(here, '..');

const HEADER = '/* AUTO-GENERATED by code/scripts/sync-annual.mjs — 勿手改；源：code/shared/%s */\n';

const jobs = [
  {
    source: 'qr.mjs',
    targets: [
      { path: join(codeRoot, 'app', 'lib', 'qr.mjs'), rewrite: null },
      { path: join(codeRoot, 'web', 'src', 'js', 'lib', 'qr.js'), rewrite: null },
    ],
  },
  {
    source: 'annual-review.mjs',
    targets: [
      { path: join(codeRoot, 'app', 'lib', 'annual-review.mjs'), rewrite: null },
      {
        path: join(codeRoot, 'web', 'src', 'js', 'lib', 'annual-review.js'),
        rewrite: [["'./qr.mjs'", "'./qr.js'"], ["'./emoji-textures.mjs'", "'./emoji-textures.js'"]],
      },
    ],
  },
  {
    // 16 个 emoji 的预渲染贴图（data URL），网页与服务端共用同一份。
    source: 'emoji-textures.mjs',
    targets: [
      { path: join(codeRoot, 'app', 'lib', 'emoji-textures.mjs'), rewrite: null },
      { path: join(codeRoot, 'web', 'src', 'js', 'lib', 'emoji-textures.js'), rewrite: null },
    ],
  },
  {
    // 缺字检查只在服务端用（网页用系统字体），所以只同步到 app/lib。
    source: 'font-cmap.mjs',
    targets: [{ path: join(codeRoot, 'app', 'lib', 'font-cmap.mjs'), rewrite: null }],
  },
];

const check = process.argv.includes('--check');
let drift = 0;

for (const job of jobs) {
  const body = readFileSync(join(codeRoot, 'shared', job.source), 'utf8');
  for (const target of job.targets) {
    let expected = HEADER.replace('%s', job.source) + body;
    for (const [from, to] of target.rewrite || []) expected = expected.split(from).join(to);
    let current = null;
    try {
      current = readFileSync(target.path, 'utf8');
    } catch {
      current = null;
    }
    if (current === expected) {
      console.log(`[annual] 一致 ${relative(codeRoot, target.path)}`);
      continue;
    }
    drift += 1;
    if (check) {
      console.log(`[annual] 漂移 ${relative(codeRoot, target.path)}`);
      continue;
    }
    mkdirSync(dirname(target.path), { recursive: true });
    writeFileSync(target.path, expected, 'utf8');
    console.log(`[annual] 已写入 ${relative(codeRoot, target.path)}`);
  }
}

if (check && drift) {
  console.error(`[annual] 有 ${drift} 个生成物与源文件不一致，请运行 node scripts/sync-annual.mjs`);
  process.exit(1);
}
